// Ids of the 3 to 5 extensions most related to this one (shared file types and users), best first.
// Picked by monetize.py. The More free viewers list shows these first.
const RELATED = ["zovo.zovo-graphviz-preview", "zovo.mermaid-viewer", "zovo.pdf-viewer-dark", "zovo.docx-viewer-vscode", "zovo.pptx-slide-viewer"];

const PUBLISHER_URL = 'https://marketplace.visualstudio.com/publishers/zovo';

const SETTING = 'showSupportLinks';

function fundingLinks() {
  return Object.keys(FUNDING_LABELS)
    .filter((k) => typeof FUNDING[k] === 'string' && /^https:\/\//.test(FUNDING[k]))
    .map((k) => ({ key: k, label: FUNDING_LABELS[k], url: FUNDING[k] }));
}

function sponsorUrl() {
  return FUNDING.github_sponsors;
}

/** The PayPal.me link, or '' while funding.json has none. */
function paypalUrl() {
  return typeof FUNDING.paypal_me === 'string' && /^https:\/\//.test(FUNDING.paypal_me) ? FUNDING.paypal_me : '';
}

function marketplaceUrl(id) {
  return `https://marketplace.visualstudio.com/items?itemName=${encodeURIComponent(id)}`;
}

/** The review tab of a listing. '' when the id is empty. */
function reviewUrl(id) {
  const x = String(id || '');
  return x ? `${marketplaceUrl(x)}&ssr=false#review-details` : '';
}

/** How closely two products are used together. 0 when they are not a pair. */
function pairWeight(a, b) {
  const x = String(a || '').toLowerCase();
  const y = String(b || '').toLowerCase();
  let best = 0;
  for (const [p, q, w] of PAIRS) {
    if ((p === x && q === y) || (p === y && q === x)) best = Math.max(best, w);
  }
  return best;
}

/** Keeps the list order for products with the same weight. */
function byPair(self, list) {
  return list
    .map((p, i) => ({ p, i, w: pairWeight(self, p.id) }))
    .sort((a, b) => (b.w - a.w) || (a.i - b.i))
    .map((x) => x.p);
}

/** Our other extensions. Live ones first, and in each group the closest pairs first. selfId is left out. */
function otherProducts(selfId) {
  const self = String(selfId || '').toLowerCase();
  const notSelf = (p) => p.id.toLowerCase() !== self;
  const live = LIVE.map(([id, name, line]) => ({ id, name, line, live: true, url: marketplaceUrl(id) })).filter(notSelf);
  const queued = QUEUED.map(([id, name, line, url]) => ({ id, name, line, live: false, url })).filter(notSelf);
  return byPair(self, live).concat(byPair(self, queued));
}

/** The related extensions for this one, best first. Live ones open the Marketplace, queued ones GitHub. */
function relatedProducts(selfId) {
  const self = String(selfId || '').toLowerCase();
  const all = otherProducts(self);
  return RELATED.map((id) => all.find((p) => p.id.toLowerCase() === String(id).toLowerCase())).filter(Boolean);
}

function sentence(line) {
  const s = String(line || '');
  return s.charAt(0).toUpperCase() + s.slice(1);
}

/** QuickPick rows: related extensions first, then the other live ones, the queued ones and the Zovo links.
 * installed(id) tells which live ones are already installed. */
function pickItems(selfId, installed) {
  const has = typeof installed === 'function' ? installed : () => false;
  const items = [];
  const related = relatedProducts(selfId);
  const relIds = new Set(related.map((p) => p.id));
  const rest = otherProducts(selfId).filter((p) => !relIds.has(p.id));
  const live = rest.filter((p) => p.live);
  const queued = rest.filter((p) => !p.live);
  const row = (p) => {
    const inst = p.live && has(p.id);
    return { label: p.name, description: !p.live ? 'GitHub' : (inst ? 'Installed' : 'Marketplace'), detail: sentence(p.line), product: p, installed: inst };
  };
  if (related.length) items.push({ label: 'Related to this extension', kind: -1 });
  for (const p of related) items.push(row(p));
  if (live.length) items.push({ label: 'More free extensions by Zovo', kind: -1 });
  for (const p of live) items.push(row(p));
  if (queued.length) items.push({ label: 'Coming soon, on GitHub', kind: -1 });
  for (const p of queued) items.push(row(p));
  items.push({ label: 'Zovo', kind: -1 });
  items.push({ label: 'All Zovo extensions', description: 'Marketplace', link: PUBLISHER_URL });
  if (GITHUB_PROFILE) items.push({ label: 'Zovo on GitHub', description: 'theluckystrike', link: GITHUB_PROFILE });
  for (const l of fundingLinks()) items.push({ label: l.label, description: 'Support the developer', link: l.url });
  return items;
}

function commandIds(prefix) {
  return { sponsor: `${prefix}.supportDeveloper`, more: `${prefix}.moreViewers` };
}

/** Commands a webview footer may run through command links (webview option enableCommandUris). */
function commandUris(prefix) {
  const c = commandIds(prefix);
  return [c.sponsor, c.more, 'workbench.action.openSettings'];
}

const FOOTER_CSS = [
  '.zovo-support{font-size:11px;line-height:16px;padding:2px 8px;color:var(--vscode-descriptionForeground);opacity:.8;white-space:nowrap}',
  '.zovo-support:hover,.zovo-support:focus-within{opacity:1}',
  '.zovo-support a{color:var(--vscode-textLink-foreground);text-decoration:none}',
  '.zovo-support a:hover,.zovo-support a:focus{text-decoration:underline}',
  '.zovo-support .zovo-sep{padding:0 4px}',
  '.zovo-support-fixed{position:fixed;right:18px;bottom:4px;z-index:20;background:var(--vscode-editor-background);border-radius:3px}',
].join('\n');

/**
 * The footer line for a webview. Returns '' when show is false.
 * extraClass: '' to put it in the page flow, 'zovo-support-fixed' to pin it to the bottom right corner.
 */
function footerHtml(prefix, show, extraClass) {
  if (show === false) return '';
  const c = commandIds(prefix);
  const settingArg = encodeURIComponent(JSON.stringify([`${prefix}.${SETTING}`]));
  const cls = extraClass ? `zovo-support ${extraClass}` : 'zovo-support';
  return `<div class="${cls}" id="zovo-support">`
    + `<a href="command:${c.sponsor}" title="Open the GitHub Sponsors page">Sponsor</a>`
    + '<span class="zovo-sep" aria-hidden="true">·</span>'
    + (paypalUrl() ? `<a href="${paypalUrl()}" title="Support the developer on PayPal">PayPal</a>`
      + '<span class="zovo-sep" aria-hidden="true">·</span>' : '')
    + `<a href="command:${c.more}" title="Other free extensions by Zovo">More free viewers</a>`
    + '<span class="zovo-sep" aria-hidden="true">·</span>'
    + (reviewUrl(SELF_ID) ? `<a href="${reviewUrl(SELF_ID)}" title="Rate or review this extension on the Marketplace">Rate</a>`
      + '<span class="zovo-sep" aria-hidden="true">·</span>' : '')
    + `<a href="command:workbench.action.openSettings?${settingArg}" title="Hide these links">Hide</a>`
    + '</div>';
}

/** Markdown version for hovers, walkthroughs and tree tooltips (needs isTrusted for command links). */
function footerMarkdown(prefix) {
  const c = commandIds(prefix);
  const rate = reviewUrl(SELF_ID);
  const pp = paypalUrl();
  return `[Sponsor](command:${c.sponsor})` + (pp ? ` · [PayPal](${pp})` : '') + ` · [More free viewers](command:${c.more})` + (rate ? ` · [Rate](${rate})` : '');
}

function showLinks(vscode, prefix) {
  try {
    return vscode.workspace.getConfiguration(prefix).get(SETTING, true) !== false;
  } catch {
    return true;
  }
}

/**
 * Registers "<Short name>: Support the developer" and "<Short name>: More free viewers".
 * opts: { vscode, context, prefix, selfId }
 */
function registerSupport(opts) {
  const { vscode, context, prefix, selfId } = opts;
  const c = commandIds(prefix);
  const open = (url) => vscode.env.openExternal(vscode.Uri.parse(url));

  async function supportDeveloper() {
    const links = fundingLinks();
    if (links.length === 0) return;
    if (links.length === 1) { await open(links[0].url); return; }
    const pick = await vscode.window.showQuickPick(
      links.map((l) => ({ label: l.label, detail: l.url, link: l })),
      { placeHolder: 'Pick a way to support the developer' }
    );
    if (pick) await open(pick.link.url);
  }

  async function moreViewers() {
    const installed = (id) => { try { return !!vscode.extensions.getExtension(id); } catch { return false; } };
    const items = pickItems(selfId, installed).map((it) => (it.kind === -1
      ? { label: it.label, kind: vscode.QuickPickItemKind ? vscode.QuickPickItemKind.Separator : -1 }
      : it));
    const pick = await vscode.window.showQuickPick(items, {
      placeHolder: 'Free extensions by Zovo, related ones first. Pick one to open its Marketplace page.',
      matchOnDetail: true,
    });
    if (!pick) return;
    if (pick.link) { await open(pick.link); return; }
    if (!pick.product) return;
    const p = pick.product;
    if (!p.live) { await open(p.url); return; }
    // The extension's Marketplace page inside VS Code, with its own Install button. Nothing installs from here.
    try { await vscode.commands.executeCommand('extension.open', p.id); } catch { await open(p.url); }
  }

  const subs = [
    vscode.commands.registerCommand(c.sponsor, supportDeveloper),
    vscode.commands.registerCommand(c.more, moreViewers),
  ];
  if (context && context.subscriptions) context.subscriptions.push(...subs);
  return { supportDeveloper, moreViewers, showLinks: () => showLinks(vscode, prefix) };
}

module.exports = {
  FUNDING, GITHUB_PROFILE, SELF_ID, LIVE, QUEUED, PAIRS, RELATED, PUBLISHER_URL, SETTING, FOOTER_CSS,
  fundingLinks, sponsorUrl, paypalUrl, marketplaceUrl, reviewUrl, pairWeight, otherProducts, relatedProducts, pickItems,
  commandIds, commandUris,
  footerHtml, footerMarkdown, showLinks, registerSupport,
};
